    longestStreak: runMine.days,
    newFriends,
    mediaSent: b.mediaSent,
    longestSpanFrom: runMine.from,
    longestSpanTo: runMine.to,
    calendar,
    activeDaysAll,
    maxDayAll,
    busiest,
    buddy,
    monthlyStar,
    starName: starEntry ? nameOf(starEntry[0]) : "",
    starUsername: starEntry ? starEntry[0] : "",
    starMonths: starEntry ? starEntry[1] : 0,
    hottestMonth,
    hottestMonthCount,
    night,
    rhythm,
    words,
    catchphrase,
    reply,
    opener,
    ranking,
    emoji,
    highlights,
    ...firstLast(b),
    money: b.extras.money,
    revoke: b.extras.revoke,
