// src/backend/wechat-data/src/query/tools/content-tools.ts
function toHits(rows, kind) {
  return rows.map((r, i) => {
    const s = (k) => typeof r[k] === "string" ? String(r[k]) : "";
    const n = (k) => typeof r[k] === "number" ? Number(r[k]) : 0;
    if (kind === "moment") {
      return {
        key: `moment:${s("username")}:${String(n("local_id"))}`,
        name: s("name") || s("username"),
        time: s("time"),
        snippet: s("snippet") || s("text"),
        source: "msg"
      };
    }
    if (kind === "favorite") {
      return {
        key: `fav:${String(n("id"))}`,
        name: `\u6536\u85CF #${String(n("id"))}`,
        time: s("time"),
        snippet: s("snippet") || s("title"),
        source: "msg"
      };
    }
    if (kind === "file") {
      return {
        key: `file:${s("fileName")}:${String(i)}`,
        name: s("fileName"),
        time: s("time"),
        snippet: n("size") > 0 ? `${(n("size") / 1024).toFixed(1)} KB` : s("md5"),
        source: "msg"
      };
    }
    return {
      key: `rec:${s("kind")}:${s("session")}:${String(i)}`,
      name: s("name"),
      time: s("time"),
      snippet: s("kind") === "transfers" ? "\u8F6C\u8D26" : "\u7EA2\u5305",
      source: "msg"
    };
  });
}
